function validate([parents, nums]) {
  const n = parents.length;
  if (n < 2 || n > 100000) return 'The tree needs 2 to 100000 nodes.';
  if (nums.length !== n) return 'parents and nums must have the same length.';
  if (parents[0] !== -1) return 'parents[0] must be -1.';
  const children = Array.from({ length: n }, () => []);
  for (let i = 1; i < n; i++) {
    if (!Number.isInteger(parents[i]) || parents[i] < 0 || parents[i] >= n || parents[i] === i) return 'Each parents[i] (i > 0) is another node from 0 to n - 1.';
    children[parents[i]].push(i);
  }
  let reached = 0;
  const stack = [0];
  while (stack.length) { const v = stack.pop(); reached++; for (const c of children[v]) stack.push(c); if (reached > n) break; }
  if (reached !== n) return 'parents must describe a tree rooted at node 0.';
  if (nums.some(v => !Number.isInteger(v) || v < 1 || v > 100000)) return 'Each value is between 1 and 100000.';
  if (new Set(nums).size !== n) return 'The values in nums must be distinct.';
  return null;
}

