function generate(rand, size) {
  const n = size === 'large' ? 2000 : 2 + Math.floor(rand() * 8);
  // Shuffle labels 1..n-1 so that parents may have larger labels than their children.
  const order = [0];
  const rest = Array.from({ length: n - 1 }, (_, i) => i + 1);
  for (let i = rest.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [rest[i], rest[j]] = [rest[j], rest[i]]; }
  order.push(...rest);
  const shape = rand();
  const parents = new Array(n).fill(-1);
  for (let k = 1; k < n; k++) {
    // shape < 0.3: a long chain-like tree; otherwise a random tree.
    const back = shape < 0.3 ? 1 + Math.floor(rand() * Math.min(k, 2)) : 1 + Math.floor(rand() * k);
    parents[order[k]] = order[k - back];
  }
  // Values: mostly a dense range so the answers are interesting, sometimes with 1 missing or with large values.
  const span = size === 'large' ? n + Math.floor(rand() * 50) : n + Math.floor(rand() * 4);
  const pool = Array.from({ length: span }, (_, i) => i + 1);
  for (let i = pool.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [pool[i], pool[j]] = [pool[j], pool[i]]; }
  const nums = pool.slice(0, n);
  if (rand() < 0.15) { const at = nums.indexOf(1); if (at !== -1) nums[at] = 100000; }
  return [parents, nums];
}
